package com.google.common.collect;

import static com.google.common.truth.Truth.assertThat;
import static org.junit.Assert.assertThrows;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Iterator;
import java.util.List;
import java.util.NoSuchElementException;
import java.util.function.Function;
import org.junit.Test;

public class IteratorsTransformJdkFunctionTest {

    @Test
    public void testTransformBasic() {
        Iterator<String> source = Arrays.asList("1", "2", "3").iterator();
        Function<String, Integer> parseInt = Integer::valueOf;
        Iterator<Integer> transformed = Iterators.transform(source, parseInt);
        List<Integer> result = new ArrayList<>();
        while (transformed.hasNext()) {
            result.add(transformed.next());
        }
        assertThat(result).containsExactly(1, 2, 3).inOrder();
    }

    @Test
    public void testTransformEmptyIterator() {
        Iterator<String> source = Arrays.<String>asList().iterator();
        Function<String, Integer> parseInt = Integer::valueOf;
        Iterator<Integer> transformed = Iterators.transform(source, parseInt);
        assertThat(transformed.hasNext()).isFalse();
        assertThrows(NoSuchElementException.class, transformed::next);
    }

    @Test
    public void testTransformWithNullElements() {
        List<String> sourceList = new ArrayList<>();
        sourceList.add("1");
        sourceList.add(null);
        sourceList.add("3");
        Iterator<String> source = sourceList.iterator();
        Function<String, Integer> parseInt = s -> s == null ? -1 : Integer.valueOf(s);
        Iterator<Integer> transformed = Iterators.transform(source, parseInt);
        List<Integer> result = new ArrayList<>();
        while (transformed.hasNext()) {
            result.add(transformed.next());
        }
        assertThat(result).containsExactly(1, -1, 3).inOrder();
    }

    @Test
    public void testTransformRemoveSupported() {
        List<String> sourceList = new ArrayList<>(Arrays.asList("a", "b", "c"));
        Iterator<String> source = sourceList.iterator();
        Function<String, String> toUpper = String::toUpperCase;
        Iterator<String> transformed = Iterators.transform(source, toUpper);
        assertThat(transformed.next()).isEqualTo("A");
        transformed.remove(); // Should remove "a" from underlying sourceList
        assertThat(sourceList).containsExactly("b", "c").inOrder();
        assertThat(transformed.next()).isEqualTo("B");
        assertThat(transformed.next()).isEqualTo("C");
        assertThat(transformed.hasNext()).isFalse();
    }

    @Test
    public void testTransformRemoveUnsupported() {
        Iterator<String> source = Arrays.asList("x", "y", "z").iterator();
        Function<String, String> identity = Function.identity();
        Iterator<String> transformed = Iterators.transform(source, identity);
        assertThat(transformed.next()).isEqualTo("x");
        // The underlying iterator does not support remove, so transformed iterator should throw.
        assertThrows(UnsupportedOperationException.class, transformed::remove);
    }

    @Test
    public void testTransformRemoveBeforeNextThrows() {
        List<String> sourceList = new ArrayList<>(Arrays.asList("p", "q"));
        Iterator<String> source = sourceList.iterator();
        Function<String, String> identity = Function.identity();
        Iterator<String> transformed = Iterators.transform(source, identity);
        assertThrows(IllegalStateException.class, transformed::remove);
    }

    @Test
    public void testTransformRemoveTwiceThrows() {
        List<String> sourceList = new ArrayList<>(Arrays.asList("m", "n"));
        Iterator<String> source = sourceList.iterator();
        Function<String, String> identity = Function.identity();
        Iterator<String> transformed = Iterators.transform(source, identity);
        transformed.next();
        transformed.remove();
        assertThrows(IllegalStateException.class, transformed::remove);
    }

    @Test
    public void testTransformWithLambda() {
        Iterator<Integer> source = Arrays.asList(1, 2, 3).iterator();
        Function<Integer, String> toString = i -> "num" + i;
        Iterator<String> transformed = Iterators.transform(source, toString);
        List<String> result = new ArrayList<>();
        transformed.forEachRemaining(result::add);
        assertThat(result).containsExactly("num1", "num2", "num3").inOrder();
    }

    @Test
    public void testTransformWithMethodReference() {
        Iterator<String> source = Arrays.asList(" hello ", " world ").iterator();
        Function<String, String> trim = String::trim;
        Iterator<String> transformed = Iterators.transform(source, trim);
        assertThat(transformed.next()).isEqualTo("hello");
        assertThat(transformed.next()).isEqualTo("world");
        assertThat(transformed.hasNext()).isFalse();
    }

    @Test
    public void testTransformNullFunctionThrows() {
        Iterator<String> source = Arrays.asList("a").iterator();
        assertThrows(NullPointerException.class, () -> Iterators.transform(source, (Function<String, String>) null));
    }

    @Test
    public void testTransformTypeChange() {
        Iterator<Integer> source = Arrays.asList(10, 20, 30).iterator();
        Function<Integer, Double> half = i -> i / 2.0;
        Iterator<Double> transformed = Iterators.transform(source, half);
        List<Double> result = new ArrayList<>();
        while (transformed.hasNext()) {
            result.add(transformed.next());
        }
        assertThat(result).containsExactly(5.0, 10.0, 15.0).inOrder();
    }

    @Test
    public void testTransformInterleavedHasNext() {
        Iterator<String> source = Arrays.asList("alpha", "beta", "gamma").iterator();
        Function<String, Integer> length = String::length;
        Iterator<Integer> transformed = Iterators.transform(source, length);
        assertThat(transformed.hasNext()).isTrue();
        assertThat(transformed.hasNext()).isTrue(); // multiple hasNext calls are safe
        assertThat(transformed.next()).isEqualTo(5);
        assertThat(transformed.next()).isEqualTo(4);
        assertThat(transformed.hasNext()).isTrue();
        assertThat(transformed.next()).isEqualTo(5);
        assertThat(transformed.hasNext()).isFalse();
    }
}

