package com.google.common.util.concurrent;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import java.io.IOException;
import java.util.concurrent.Callable;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.Test;

/**
 * Unit tests for {@link RetryExecutor}.
 */
public class RetryExecutorTest {

    @Test
    public void testCalculateDelay_fixedBackoff() {
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(5)
                .backoffMillis(1000)
                .exponentialBackoff(false)
                .build();

        // Use reflection to access private method for testing
        java.lang.reflect.Method calculateDelayMethod = null;
        try {
            calculateDelayMethod = RetryExecutor.class.getDeclaredMethod("calculateDelay", int.class);
            calculateDelayMethod.setAccessible(true);
            for (int attempt = 0; attempt < 5; attempt++) {
                long delay = (long) calculateDelayMethod.invoke(executor, attempt);
                assertEquals(1000L, delay);
            }
        } catch (Exception e) {
            fail("Reflection failed: " + e.getMessage());
        }
    }

    @Test
    public void testCalculateDelay_exponentialBackoff() {
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(5)
                .backoffMillis(1000)
                .exponentialBackoff(true)
                .build();

        java.lang.reflect.Method calculateDelayMethod = null;
        try {
            calculateDelayMethod = RetryExecutor.class.getDeclaredMethod("calculateDelay", int.class);
            calculateDelayMethod.setAccessible(true);
            // attempt 0: 2^0 * 1000 = 1000
            assertEquals(1000L, (long) calculateDelayMethod.invoke(executor, 0));
            // attempt 1: 2^1 * 1000 = 2000
            assertEquals(2000L, (long) calculateDelayMethod.invoke(executor, 1));
            // attempt 2: 2^2 * 1000 = 4000
            assertEquals(4000L, (long) calculateDelayMethod.invoke(executor, 2));
            // attempt 3: 2^3 * 1000 = 8000
            assertEquals(8000L, (long) calculateDelayMethod.invoke(executor, 3));
            // attempt 4: 2^4 * 1000 = 16000
            assertEquals(16000L, (long) calculateDelayMethod.invoke(executor, 4));
        } catch (Exception e) {
            fail("Reflection failed: " + e.getMessage());
        }
    }

    @Test
    public void testExecute_successOnFirstAttempt() throws Exception {
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(3)
                .backoffMillis(100)
                .exponentialBackoff(false)
                .build();

        String result = executor.execute(() -> "success");
        assertEquals("success", result);
    }

    @Test
    public void testExecute_retryAndSuccess() throws Exception {
        AtomicInteger attempts = new AtomicInteger(0);
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(3)
                .backoffMillis(10) // small delay for test speed
                .exponentialBackoff(false)
                .retryOn(IOException.class)
                .build();

        Callable<String> task = () -> {
            int attempt = attempts.incrementAndGet();
            if (attempt < 3) {
                throw new IOException("Simulated failure " + attempt);
            }
            return "success after " + attempt;
        };

        String result = executor.execute(task);
        assertEquals("success after 3", result);
        assertEquals(3, attempts.get());
    }

    @Test
    public void testExecute_exponentialBackoffDelayApplied() throws Exception {
        AtomicInteger attempts = new AtomicInteger(0);
        AtomicLong lastAttemptTime = new AtomicLong(0);
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(4)
                .backoffMillis(50)
                .exponentialBackoff(true)
                .retryOn(IOException.class)
                .build();

        Callable<String> task = () -> {
            int attempt = attempts.incrementAndGet();
            long currentTime = System.currentTimeMillis();
            if (attempt > 1) {
                // Verify that the delay between attempts is roughly exponential
                long elapsed = currentTime - lastAttemptTime.get();
                long expectedDelay = (long) (Math.pow(2, attempt - 2) * 50);
                // Allow some tolerance for timing inaccuracies
                assertTrue("Attempt " + attempt + ": elapsed " + elapsed + " should be >= " + expectedDelay,
                        elapsed >= expectedDelay - 10);
            }
            lastAttemptTime.set(currentTime);
            if (attempt < 4) {
                throw new IOException("Fail attempt " + attempt);
            }
            return "success";
        };

        String result = executor.execute(task);
        assertEquals("success", result);
        assertEquals(4, attempts.get());
    }

    @Test
    public void testExecute_nonRetryableExceptionThrownImmediately() {
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(3)
                .backoffMillis(100)
                .exponentialBackoff(false)
                .retryOn(IOException.class)
                .build();

        AtomicInteger attempts = new AtomicInteger(0);
        Callable<String> task = () -> {
            attempts.incrementAndGet();
            throw new RuntimeException("Non-retryable");
        };

        assertThrows(RuntimeException.class, () -> executor.execute(task));
        assertEquals(1, attempts.get()); // Should not retry
    }

    @Test
    public void testExecute_exhaustRetriesThrowsLastException() {
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(3)
                .backoffMillis(10)
                .exponentialBackoff(false)
                .retryOn(IOException.class)
                .build();

        AtomicInteger attempts = new AtomicInteger(0);
        Callable<String> task = () -> {
            attempts.incrementAndGet();
            throw new IOException("Failed attempt " + attempts.get());
        };

        IOException thrown = assertThrows(IOException.class, () -> executor.execute(task));
        assertEquals("Failed attempt 3", thrown.getMessage());
        assertEquals(3, attempts.get());
    }

    @Test
    public void testExecute_noRetryableExceptionsConfiguredRetriesAll() throws Exception {
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(3)
                .backoffMillis(10)
                .exponentialBackoff(false)
                // No retryOn calls, so all exceptions are retryable
                .build();

        AtomicInteger attempts = new AtomicInteger(0);
        Callable<String> task = () -> {
            int attempt = attempts.incrementAndGet();
            if (attempt < 3) {
                throw new RuntimeException("Any exception");
            }
            return "success";
        };

        String result = executor.execute(task);
        assertEquals("success", result);
        assertEquals(3, attempts.get());
    }

    @Test
    public void testExecute_interruptedDuringSleepThrowsLastException() throws Exception {
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(3)
                .backoffMillis(1000) // long delay
                .exponentialBackoff(false)
                .retryOn(IOException.class)
                .build();

        AtomicInteger attempts = new AtomicInteger(0);
        Thread testThread = Thread.currentThread();
        Callable<String> task = () -> {
            attempts.incrementAndGet();
            if (attempts.get() == 1) {
                // Schedule an interrupt during the sleep
                new Thread(() -> {
                    try {
                        Thread.sleep(50);
                    } catch (InterruptedException e) {
                        // ignore
                    }
                    testThread.interrupt();
                }).start();
                throw new IOException("First failure");
            }
            return "should not reach";
        };

        // The execute method should throw the lastException (IOException) when interrupted
        IOException thrown = assertThrows(IOException.class, () -> executor.execute(task));
        assertEquals("First failure", thrown.getMessage());
        assertEquals(1, attempts.get());
        // Clear interrupt flag for subsequent tests
        Thread.interrupted();
    }

    @Test
    public void testBuilderValidation() {
        // maxRetries must be positive
        IllegalArgumentException e1 = assertThrows(IllegalArgumentException.class,
                () -> RetryExecutor.builder().maxRetries(0).build());
        assertEquals("maxRetries must be positive", e1.getMessage());

        // backoffMillis must be non-negative
        IllegalArgumentException e2 = assertThrows(IllegalArgumentException.class,
                () -> RetryExecutor.builder().backoffMillis(-1).build());
        assertEquals("backoffMillis must be non-negative", e2.getMessage());
    }

    @Test
    public void testExecute_nullTaskThrows() {
        RetryExecutor executor = RetryExecutor.builder().build();
        assertThrows(NullPointerException.class, () -> executor.execute(null));
    }
}

