package com.google.common.collect;

import static com.google.common.truth.Truth.assertThat;
import static org.junit.Assert.assertThrows;

import java.util.NoSuchElementException;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;

@RunWith(JUnit4.class)
public class EvictingQueueTest {

  @Test
  public void testAdd_whenMaxSizeZero_returnsFalseAndDoesNotAdd() {
    EvictingQueue<String> queue = EvictingQueue.create(0);
    boolean result = queue.add("hello");
    assertThat(result).isFalse();
    assertThat(queue).isEmpty();
    assertThat(queue.contains("hello")).isFalse();
    assertThat(queue.size()).isEqualTo(0);
  }

  @Test
  public void testAdd_whenMaxSizeZero_multipleCallsAllReturnFalse() {
    EvictingQueue<Integer> queue = EvictingQueue.create(0);
    assertThat(queue.add(1)).isFalse();
    assertThat(queue.add(2)).isFalse();
    assertThat(queue.add(3)).isFalse();
    assertThat(queue).isEmpty();
    assertThat(queue.size()).isEqualTo(0);
  }

  @Test
  public void testAdd_whenMaxSizeZero_offerAlsoReturnsFalse() {
    EvictingQueue<String> queue = EvictingQueue.create(0);
    boolean result = queue.offer("test");
    assertThat(result).isFalse();
    assertThat(queue).isEmpty();
    assertThat(queue.contains("test")).isFalse();
  }

  @Test
  public void testAdd_whenMaxSizePositive_addsAndReturnsTrue() {
    EvictingQueue<String> queue = EvictingQueue.create(3);
    assertThat(queue.add("a")).isTrue();
    assertThat(queue.add("b")).isTrue();
    assertThat(queue.add("c")).isTrue();
    assertThat(queue).containsExactly("a", "b", "c").inOrder();
    assertThat(queue.size()).isEqualTo(3);
  }

  @Test
  public void testAdd_whenMaxSizePositive_evictsOnOverflowAndReturnsTrue() {
    EvictingQueue<Integer> queue = EvictingQueue.create(2);
    assertThat(queue.add(1)).isTrue();
    assertThat(queue.add(2)).isTrue();
    assertThat(queue.add(3)).isTrue();
    assertThat(queue).containsExactly(2, 3).inOrder();
    assertThat(queue.size()).isEqualTo(2);
  }

  @Test
  public void testAdd_whenMaxSizePositive_offerAlsoReturnsTrue() {
    EvictingQueue<String> queue = EvictingQueue.create(1);
    assertThat(queue.offer("x")).isTrue();
    assertThat(queue).containsExactly("x");
  }

  @Test
  public void testAdd_nullThrows() {
    EvictingQueue<Object> queue = EvictingQueue.create(5);
    assertThrows(NullPointerException.class, () -> queue.add(null));
  }

  @Test
  public void testAdd_nullThrowsEvenWhenMaxSizeZero() {
    EvictingQueue<Object> queue = EvictingQueue.create(0);
    assertThrows(NullPointerException.class, () -> queue.add(null));
  }

  @Test
  public void testAddAll_whenMaxSizeZero_returnsFalse() {
    EvictingQueue<String> queue = EvictingQueue.create(0);
    boolean result = queue.addAll(java.util.Arrays.asList("a", "b", "c"));
    assertThat(result).isFalse();
    assertThat(queue).isEmpty();
  }

  @Test
  public void testAddAll_whenMaxSizePositive_returnsTrueIfAnyAdded() {
    EvictingQueue<String> queue = EvictingQueue.create(5);
    boolean result = queue.addAll(java.util.Arrays.asList("x", "y"));
    assertThat(result).isTrue();
    assertThat(queue).containsExactly("x", "y").inOrder();
  }

  @Test
  public void testRemainingCapacity_whenMaxSizeZero_isZero() {
    EvictingQueue<Object> queue = EvictingQueue.create(0);
    assertThat(queue.remainingCapacity()).isEqualTo(0);
  }

  @Test
  public void testContainsAfterAdd_whenMaxSizeZero_alwaysFalse() {
    EvictingQueue<String> queue = EvictingQueue.create(0);
    boolean added = queue.add("element");
    assertThat(added).isFalse();
    assertThat(queue.contains("element")).isFalse();
  }

  @Test
  public void testIterator_whenMaxSizeZero_isEmpty() {
    EvictingQueue<String> queue = EvictingQueue.create(0);
    assertThat(queue.iterator().hasNext()).isFalse();
  }

  @Test
  public void testPoll_whenMaxSizeZero_returnsNull() {
    EvictingQueue<String> queue = EvictingQueue.create(0);
    assertThat(queue.poll()).isNull();
  }

  @Test
  public void testRemove_whenMaxSizeZero_throwsNoSuchElement() {
    EvictingQueue<String> queue = EvictingQueue.create(0);
    assertThrows(NoSuchElementException.class, queue::remove);
  }

  @Test
  public void testPeek_whenMaxSizeZero_returnsNull() {
    EvictingQueue<String> queue = EvictingQueue.create(0);
    assertThat(queue.peek()).isNull();
  }

  @Test
  public void testElement_whenMaxSizeZero_throwsNoSuchElement() {
    EvictingQueue<String> queue = EvictingQueue.create(0);
    assertThrows(NoSuchElementException.class, queue::element);
  }
}

