    Iterator<Long> iterator = list.iterator();
    assertTrue(iterator instanceof PrimitiveIterator.OfLong);
    assertThat(iterator.hasNext()).isFalse();
  }

  @Test
  public void testIteratorConsistencyWithListContents() {
    ImmutableLongArray array = ImmutableLongArray.of(42L, 99L, -5L, 0L);
    List<Long> list = array.asList();
    PrimitiveIterator.OfLong iterator = (PrimitiveIterator.OfLong) list.iterator();

    for (int i = 0; i < array.length(); i++) {
      assertTrue(iterator.hasNext());
      assertThat(iterator.nextLong()).isEqualTo(array.get(i));
    }
    assertThat(iterator.hasNext()).isFalse();
  }

