  public void testIteratorRemoveUnsupported() {
    List<Long> list = ImmutableLongArray.of(1L, 2L).asList();
    Iterator<Long> iterator = list.iterator();
    iterator.next();
    assertThrows(UnsupportedOperationException.class, iterator::remove);
  }
}

