package com.google.common.io;

import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

public class BaseEncodingTest {

    public void testEncodingStreamWriteAfterCloseThrows() throws IOException {
        BaseEncoding base64 = BaseEncoding.base64();
        StringWriter writer = new StringWriter();
        try (java.io.OutputStream out = base64.encodingStream(writer)) {
            out.write('A');
            out.close();
            try {
                out.write('B');
                throw new AssertionError("Expected IOException");
            } catch (IOException e) {
                if (!"Stream is closed".equals(e.getMessage())) {
                    throw new AssertionError("Expected 'Stream is closed' but got: " + e.getMessage());
                }
            }
        }
    }

    public void testEncodingStreamFlushAfterCloseThrows() throws IOException {
        BaseEncoding base64 = BaseEncoding.base64();
        StringWriter writer = new StringWriter();
        try (java.io.OutputStream out = base64.encodingStream(writer)) {
            out.write('A');
            out.close();
            try {
                out.flush();
                throw new AssertionError("Expected IOException");
            } catch (IOException e) {
                if (!"Stream is closed".equals(e.getMessage())) {
                    throw new AssertionError("Expected 'Stream is closed' but got: " + e.getMessage());
                }
            }
        }
    }

    public void testEncodingStreamCloseIdempotent() throws IOException {
        BaseEncoding base64 = BaseEncoding.base64();
        StringWriter writer = new StringWriter();
        java.io.OutputStream out = base64.encodingStream(writer);
        out.write('A');
        out.close();
        // Second close should not throw
        out.close();
        // Verify the output is correct (no duplicate padding)
